package com.nextgen.gameaggregator.vendor.aviatrix.api.result;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.nextgen.gameaggregator.enums.BetStatus;
import com.nextgen.gameaggregator.operator.wallet.rollback.RollbackData;
import com.nextgen.gameaggregator.operator.wallet.settled.BetResultData;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import lombok.Data;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;

@Data
@JsonIgnoreProperties(ignoreUnknown = true)
public class ResultDto implements BetResultData, RollbackData {

    @NotBlank
    @Size(max = 255)
    private String betId; //vendor's unique bet id, fixed throughout the flow
    @NotBlank
    @Size(max = 255)
    private String cid; //channel id generated by vendor for identification
    @NotBlank
    @Size(max = 255)
    private String sessionToken;
    @NotBlank
    @Size(max = 50)
    private String playerId; //vendor player id
    @NotBlank
    @Size(max = 255)
    private String productId; // game id
    @NotBlank
    @Size(max = 255)
    private String txId; // transaction id, unique for every transaction
    @NotBlank
    @Size(max = 255)
    private String roundId; //round id, fixed throughout the flow
    @NotNull
    @Digits(integer = 20, fraction = 0)
    private BigInteger amount; //bet amount
    @NotBlank
    @Size(max = 5)
    private String currency; //currency used
    @NotNull
    @Digits(integer = 10, fraction = 0)
    private Long timestamp; //10-digit unix timestamp
    @NotBlank
    @Size(max = 255)
    private String operation; //parameters to differentiate settle or cancel process (SettleBet, CancelBet)

    @Override
    public String getExternalTransactionId() {
        return this.betId;
    }

    @Override
    public String getVendorBetId() {
        return this.betId;
    }

    @Override
    public String getRoundId() {
        return this.roundId;
    }

    @Override
    public String getGameId() {
        return this.productId;
    }

    @Override
    public BigDecimal getBetAmount() {
        return null;
    }

    @Override
    public BigDecimal getWinAmount() {
        return new BigDecimal(this.amount).divide(BigDecimal.valueOf(100), 2, RoundingMode.DOWN);
    }

    @Override
    public BigDecimal getWinLoss() {
        return null;
    }

    @Override
    public BigDecimal getEffectiveTurnover() {
        return null;
    }

    @Override
    public Long getVendorBetTime() {
        return null;
    }

    @Override
    public Long getResultTime() {
        return this.timestamp * 1000;
    }

    @Override
    public Long getVendorSettleTime() {
        return this.timestamp * 1000;
    }

    @Override
    public BigDecimal getJackpotAmount() {
        return null;
    }

    @Override
    public Integer getIsFreespin() {
        return 0;
    }

    @Override
    public BetStatus getBetStatus() {
        return BetStatus.SETTLED;
    }

    @Override
    public String getRollbackId() {
        return this.betId;
    }

    @Override
    public Long getVendorSettledTime() {
        return this.timestamp * 1000;
    }

    @Override
    public boolean getShouldSettleByBet()  {
        return true;
    }
}
